/**
 * How the raw offsets grow with the body (log-log OLS over the corpus):
 * slope 1 = proportional to body size, slope 0 = constant in absolute units.
 * `heightFrac`/`forwardFrac` are the same regression on the FRACTION, so a slope near 0
 * says the body-share itself is size-free (which is what makes fractions the right unit).
 */
export const MOTION_SCALING = {
  height: { n: 137, slope: 1.152, r2: 0.449 },
  forward: { n: 119, slope: 0.758, r2: 0.167 },
  windupBack: { n: 113, slope: 0.452, r2: 0.016 },
  windupUp: { n: 116, slope: 0.622, r2: 0.028 },
  windupTravel: { n: 137, slope: 0.946, r2: 0.126 },
  heightFrac: { n: 137, slope: 0.152, r2: 0.014 },
  forwardFrac: { n: 119, slope: -0.242, r2: 0.02 },
};

/** The same, against ARM LENGTH instead of body height. */
export const MOTION_SCALING_ARM = {
  height: { n: 41, slope: 1.047, r2: 0.269 },
  forward: { n: 33, slope: 0.242, r2: 0.027 },
  travel: { n: 43, slope: 0.211, r2: 0.007 },
};

const VALID_CLASSES = new Set(MOTION_CLASSES);
const CELL_ORDER = ["hH","fH","lH","handHH","handFH","backH","upH","windup","flight"];

/**
 * A requested quantile as the record's own key: 0.1 -> "p10", 0.5 -> "p50", 0.9 -> "p90"; anything else is
 * the median. The records are keyed p10/p50/p90 (this file's own convention), so a caller asking for a
 * quantile has to be mapped onto those keys — the previous lookup indexed the records with the raw number
 * ("0.9") and silently returned the median every time.
 */
const quantKey = (quantile) => { const p = Math.round(Number(quantile) * 100); return p === 10 ? "p10" : p === 90 ? "p90" : "p50"; };

/** A compact class x size cell ([p10,p50,p90] triples) as the same {p10,p50,p90} records. */
function fullCell(cell) {
  const o = { n: cell.n };
  for (const k of CELL_ORDER) if (Array.isArray(cell[k])) o[k] = { p10: cell[k][0], p50: cell[k][1], p90: cell[k][2] };
  return o;
}

/**
 * The aggregate for a class (optionally narrowed by size class): the class x size cell when it has at
 * least `minCell` casts, MERGED over the class record (the cell wins where it has a measure), else the
 * class record alone. Returns null for an unknown class.
 */
export function motionFor(emitterClass, sizeClass = null, { minCell = 4 } = {}) {
  if (!VALID_CLASSES.has(emitterClass)) return null;
  // An EYE emitter has no spell cast of its own in the corpus (2 throws only): it is a head-front
  // emitter, so the mouth record is its data. Resolve it here so a solver never gets null for a class
  // this file lists.
  const cls = MOTION[emitterClass] ? emitterClass : (emitterClass === "eyes" ? "mouth" : emitterClass);
  const alias = cls === emitterClass ? null : "class:" + emitterClass + "->" + cls;
  const base = MOTION[cls] ? { ...MOTION[cls], source: alias ?? "class" } : null;
  const cell = sizeClass ? MOTION_BY_CLASS_SIZE?.[cls]?.[sizeClass] : null;
  if (base && cell && cell.n >= minCell) return { ...base, ...fullCell(cell), source: (alias ? alias + "+size" : "class+size") };
  return base;
}

/**
 * The release point a solver should aim for, in the model's own frame:
 *   { height, forward, lateral } in model units (+y DOWN, so the caller places the emitter at
 *   y = floor - height; +z forward).
 * Fractions are the class medians (p50); pass `quantile` 0.1 / 0.9 to stay inside the disc's spread.
 */
export function releasePoint({ emitterClass, sizeClass = null, bodyHeight, quantile = 0.5 }) {
  const m = motionFor(emitterClass, sizeClass);
  const H = Number(bodyHeight);
  if (!m || !(H > 0)) return null;
  const q = quantKey(quantile);
  const pick = (a, fallback) => (a && a[q] != null ? a[q] : a && a.p50 != null ? a.p50 : fallback);
  return {
    height: pick(m.hH, 0) * H, forward: pick(m.fH, 0) * H, lateral: pick(m.lH, 0) * H,
    source: m.source, quantile: q, unit: "body",
  };
}

/**
 * The WRIST target for an arm class - where the hand itself has to be (the releasePoint of a prop arm is
 * the weapon's muzzle, which is not a place a hand can be put). Falls back to releasePoint for a class
 * with no hand point (a mouth or a body emitter).
 */
export function handPoint({ emitterClass, sizeClass = null, bodyHeight, quantile = 0.5 }) {
  const m = motionFor(emitterClass, sizeClass);
  const H = Number(bodyHeight);
  if (!m || !(H > 0)) return null;
  if (m.handHH == null) return { ...releasePoint({ emitterClass, sizeClass, bodyHeight, quantile }), source: (m.source ?? "class") + ":emitter" };
  const q = quantKey(quantile);
  const pick = (a, fallback) => (a && a[q] != null ? a[q] : a && a.p50 != null ? a.p50 : fallback);
  return {
    height: pick(m.handHH, 0) * H, forward: pick(m.handFH, 0) * H, lateral: pick(m.handLH, 0) * H,
    source: m.source, quantile: q, unit: "body",
  };
}

/**
 * The emitter's position RELATIVE TO ITS SHOULDER, in arm lengths - what an arm solver needs to know
 * about the limb's own shape (a hand 0.9 arm lengths forward and 0.3 up is a raised, extended arm).
 * Null for a class with no arm measure.
 */
export function armShape({ emitterClass, sizeClass = null, armLength, quantile = 0.5, hand = false }) {
  const m = motionFor(emitterClass, sizeClass);
  const L = Number(armLength);
  if (!m || !(L > 0)) return null;
  const q = quantKey(quantile);
  const pick = (a, fallback) => (a && a[q] != null ? a[q] : a && a.p50 != null ? a.p50 : fallback);
  const Hk = hand ? "handHL" : "hL", Fk = hand ? "handFL" : "fL";
  if (m[Hk] == null || m[Fk] == null) return null;
  return { above: pick(m[Hk], 0) * L, forward: pick(m[Fk], 0) * L, source: m.source, quantile: q };
}

/**
 * The wind-up excursion and the phase timing a solver should use for a class:
 *   { back, up, travel } in model units, { windup, flight, follow } in ticks.
 */
export function windupFor({ emitterClass, sizeClass = null, bodyHeight, quantile = 0.5 }) {
  const m = motionFor(emitterClass, sizeClass);
  const H = Number(bodyHeight);
  if (!m || !(H > 0)) return null;
  const q = quantKey(quantile);
  const pick = (a, f) => (a && a[q] != null ? a[q] : a && a.p50 != null ? a.p50 : f);
  return {
    back: pick(m.backH, 0) * H, up: pick(m.upH, 0) * H, travel: pick(m.travelH, 0) * H,
    speed: pick(m.speedH, 0) * H,
    windup: pick(m.windup, 0), flight: pick(m.flight, 0), follow: pick(m.follow, 0),
    peakBefore: pick(m.peakBefore, 0), quantile: q, source: m.source,
  };
}
